    - Neue protected Methoden `selectCategory(categoryId: string)`, `selectSubcategory(subcategoryId: string)`, `clearSelection()`:
      ```typescript
      protected selectCategory(categoryId: string): void {
        if (this.loading()) { return; }
        this.selectedCategoryId.set(categoryId);
        this.selectedSubcategoryId.set(null);
        this.loadPage(1);
      }

      protected selectSubcategory(subcategoryId: string): void {
        if (this.loading()) { return; }
        this.selectedSubcategoryId.set(subcategoryId);
        this.loadPage(1);
      }

      protected clearSelection(): void {
        if (this.loading()) { return; }
        this.selectedCategoryId.set(null);
        this.selectedSubcategoryId.set(null);
        this.loadPage(1);
      }
      ```
