1	using Microsoft.EntityFrameworkCore;
2	using seed_b_backend.Api.Data;
3	using seed_b_backend.Api.Domain;
4	
5	namespace seed_b_backend.Api.Application;
6	
7	public class CatalogService(AppDbContext context)
8	{
9	    public const int PageSize = 20;
10	
11	    public async Task<PagedResult<Product>> GetProductsAsync(int page, string? categoryId = null, string? subcategoryId = null, CancellationToken ct = default)
12	    {
13	        var query = context.Products.AsQueryable();
14	        if (!string.IsNullOrEmpty(subcategoryId))
15	        {
16	            query = query.Where(p => p.SubcategoryId == subcategoryId);
17	        }
18	        else if (!string.IsNullOrEmpty(categoryId))
19	        {
20	            query = query.Where(p => p.Subcategory!.CategoryId == categoryId);
21	        }
22	
23	        var totalCount = await query.CountAsync(ct);
24	
25	        query = query.OrderBy(p => p.Id);
26	
27	        var skip = (long)(page - 1) * PageSize;
28	
29	        var items = page < 1 || skip > int.MaxValue
30	            ? new List<Product>()
31	            : await query.Skip((int)skip).Take(PageSize).ToListAsync(ct);
32	
33	        return new PagedResult<Product>
34	        {
35	            Items = items,
36	            Page = page,
37	            PageSize = PageSize,
38	            TotalCount = totalCount
39	        };
40	    }
41	
42	    public async Task<List<Category>> GetCategoriesAsync(CancellationToken ct = default)
43	    {
44	        return await context.Categories
45	            .Include(c => c.Subcategories.OrderBy(s => s.Id))
46	            .OrderBy(c => c.Id)
47	            .ToListAsync(ct);
48	    }
49	}
